"""Reviewed narrative sections; separate from figure and evidence preparation."""
from reportlab.lib.units import mm
from production.report_equations import equation


def ask(text):
    return '<font color="#b22222">[Jason: ' + text + ']</font>'


def write_sections(a, assets, means, chosen, task_screen):
    a.p('Working draft. Red brackets identify questions for Jason.', 'caption')
    a.h('1 Study objective and experimental data')
    a.p('We investigated whether a compact numerical fingerprint could capture individual differences in interception movements and reproduce a participant\'s movement distributions. The principal setting used three latent values, with eight providing a higher-capacity comparison. Neural encoder-decoder models were compared with spline-based dimensionality reduction and regression on reconstruction, feature distributions and individual information. These comparisons inform model selection for an interactive dashboard.')
    a.h('1.1 Experimental task', True)
    a.p('The recordings were provided by Jason Friedman\'s laboratory. Participants moved their finger from a starting region toward a fixed interception region. A circular target appeared on either side of the display and subsequently moved horizontally toward the interception region. Participants were instructed to reach that region while the moving target was inside it. Successful performance therefore required coordinating finger arrival with target arrival (Figure 1).')
    a.p('The target appeared at one of six starting locations: three on the left and three on the right. Each starting-position category was associated with a range of speeds, from which a continuous target speed was randomly selected for each trial. Starting position and speed were therefore related by the design, rather than varied independently.')
    a.table([['Category','Starting-position setting','Target-speed range'],['1','120','255-300 mm/s'],['2','140','298-350 mm/s'],['3','160','340-400 mm/s']], '<b>Table 1.</b> Nominal stimulus settings supplied by the laboratory; every category occurred on both sides. '+ask('Are the starting-position values in mm, and relative to which reference?'), [30*mm,68*mm,68*mm])
    a.p('The experiment included central-fixation and free-eye-movement conditions. This study analyzed only the free-eye-movement condition (condition 2), as specified by the laboratory. Within this subset, the modeling variables were starting-position category, starting side and executed target speed.')
    a.h('1.2 Recordings and analysis sample', True)
    a.p('Finger position was recorded in three dimensions at 240 Hz using a Polhemus Liberty magnetic motion-capture system. Each CSV contained positions, sensor orientation, a frame counter, a reception timestamp and an event marker. Orientation was excluded. Frame counters supplied the sampling time base because reception times need not follow a regular sampling interval. Paired MATLAB files supplied the target trajectory at 60 Hz, event times and outcome labels.')
    a.p('The available condition-2 dataset comprised 4,763 trials from 28 participants. Four trials without an arrival event and 27 with arrival more than one second after the target window ended were excluded, leaving 4,732 trials. Early-arrival and fixation-warning labels were retained. '+ask('Confirm the late-arrival exclusion and retention of fixation-warning trials in condition 2.'))
    a.p('Twenty-six participants contributed 171-180 retained trials each; the other two contributed 60 and 28. These two participants had only 60 and 29 recordings available, respectively. Thus, the small counts mainly reflect incomplete available sessions rather than extensive exclusion. The median retained count was 179.5. '+ask('Are the missing recordings for subject02 and subject41 unavailable files or incomplete sessions, and should both participants remain in the analysis?'))
    a.page()
    a.h('1.3 Task and recorded-movement examples', True)
    a.figure(task_screen, '<b>Figure 1.</b> Original free-eye-movement instruction screen supplied with the stimulus files (instructions2.jpg). The lower red square indicates the starting region; the upper blue square is the interception region. The instructions require finger arrival while the moving target occupies that region and permit free eye movements. This is the task display, not a photograph of the apparatus.', 90*mm)
    a.figure(assets/'recorded_examples.png', '<b>Figure 2.</b> Recorded movements from subject01, selected as the first participant in identifier order. Left: all 180 retained trials, colored by target starting category; line style indicates target side. Right: one trial selected by median modeled duration, before inspecting model errors. Positions are filtered, aligned to target motion and translated to a common starting point. Panels share axis limits, with lateral variation enlarged relative to forward displacement. These are recorded data, not model outputs.', 90*mm)
    a.p('Repeated trials provide the observations from which a participant-specific distribution can be estimated. The spatial paths illustrate variation in the recordings, while the subsequent evaluation also examines initiation time, movement duration and derived kinematic features. Figure 3 shows how an individual recording enters the models.')
    a.page()
    a.h('2 From recordings to model inputs')
    a.p('Trial durations and the number of recorded samples varied. To compare and compress trajectories with a common model, we mapped every retained recording to 100 positions spanning the same relative interval within the trial. This temporal normalization was applied after establishing a regular sampling grid, filtering and selecting the modeled window.')
    a.h('2.1 Sampling grid, filtering and event alignment', True)
    a.p('Samples sharing a frame counter were averaged, and missing counters were filled by linear interpolation. The resulting grid had a 1/240 s interval. A fourth-order Butterworth low-pass filter with a 10 Hz cutoff was applied forward and backward to the three position coordinates. Filtering attenuated rapid fluctuations before resampling and speed-based onset detection.')
    a.p('Marker 5 identified target appearance. Target-motion onset was located from the first nonzero displacement in the executed target trajectory and mapped to the nearest tracker frame. The modeled window ran from that frame to the final recorded tracker sample. It therefore included waiting after target motion began. '+ask('Confirm the target-motion alignment and whether the earlier appearance-to-motion interval should also be modeled.'))
    a.p('The final tracker sample served as the arrival proxy; the event audit placed it, on average, 26.2 ms before the MATLAB arrival event (SD 3.6 ms). '+ask('Confirm the arrival-event meaning and whether this endpoint is appropriate.'))
    a.h('2.2 Temporal and spatial normalization', True)
    a.p('For a window containing L samples, sample i was assigned phase u<sub>i</sub> = i/(L - 1). A cubic interpolant S was fitted through the filtered coordinates and evaluated at 100 phases u<sub>j</sub> = j/99, including both endpoints. Subtracting the first position then aligned the start of every trajectory:')
    equation(a,assets,'resample')
    a.p('This operation changes the sampling grid without fitting the later five-knot model. A phase of 0.5 denotes halfway through the selected time interval, not halfway along the traveled path. The resulting points preserve relative temporal progression, but the array alone does not specify duration in seconds. Spatial normalization translates the path; it does not rotate it or scale its amplitude.')
    a.figure(assets/'resampling_example.png', '<b>Figure 3.</b> One subject01 trial before and after temporal normalization. The filtered forward-position trace uses physical elapsed time on the left. The right panel shows the same trace against phase, with all 100 resampled points. The same operation is applied to the other coordinates. Resampling does not create 100 independent observations.', 61*mm)
    a.p('The analysis used x and y from the normalized 3-D trajectory, producing a 100 x 2 matrix P, flattened in time order into 200 neural input values. '+ask('Confirm that x-y is the task plane and confirm tracker position units (mm or cm).')+' Until confirmed, trajectory errors are reported in squared tracker units.')
    a.page()
    a.h('2.3 Duration targets and participant separation', True)
    a.p('Physical timing was retained separately from the phase-normalized coordinates. Finger onset was the first post-target-motion sample with 3-D speed above 5 tracker units/s for three consecutive frames. Initiation time was measured from target motion to this onset; movement time was measured from onset to the final sample. If no sustained crossing was found, the implementation used target motion as onset. '+ask('Confirm the onset threshold, persistence rule and fallback.'))
    a.p('The two durations were transformed as log(t + 0.001), with t in seconds, and standardized using training-trial means and standard deviations. They were supervised prediction targets and were not supplied as encoder inputs. Predictions were converted back to seconds by reversing standardization and the log transform, with negative values clipped to zero.')
    a.p('Four fixed participant folds contained 17 training, four validation and seven test participants each. Every participant appeared in a test fold once. Parameters and normalization were fitted on training participants; validation participants determined hyperparameters and checkpoints. Neural training used inverse-trial-count sampling to give each training participant equal expected sampling weight. Reported errors were averaged within each test participant before averaging participants equally.')
    a.p('Reconstruction used each complete held-out trajectory as an input and compared its decoded output with that trajectory. For participant fingerprints and generation, test trials were instead divided into disjoint, condition-stratified context and query sets. Only context codes contributed to the fingerprint; query movements supplied the evaluation distribution. These distinct input requirements were maintained throughout the comparisons.')
    a.h('3 Compact trajectory models')
    a.p('Spline + PCA and the neural encoders provided alternative mappings from the same observed trajectory to n latent values. The primary comparison used n=3, with n=8 testing a less restrictive representation. CVAE and spline runs also included n=2 and n=4; the matched neural ablations were evaluated at three and eight dimensions. The spline model supplied a smooth linear representation, while the neural models learned nonlinear encoder-decoder mappings.')
    a.figure(assets/'models.png', '<b>Figure 4.</b> Alternative model pipelines. Each representation compresses a single trial to n values. A participant fingerprint is subsequently formed by averaging context-trial codes. The spline timing regression is separate from its shape reconstruction.', 57*mm)
    a.page()
    a.h('3.1 Spline fitting and PCA compression', True)
    a.p('The spline representation first replaced each 100-point coordinate sequence with a fitted smooth curve. We used cubic B-splines with five fixed interior knots at phases 1/6, 2/6, 3/6, 4/6 and 5/6. These define nine basis functions per coordinate. The knot locations were shared across trials; the fitted coefficients varied between trials.')
    a.p('Let B be the 100 x 9 matrix of basis values at the resampling phases. For each trial, the nine x coefficients and nine y coefficients were obtained by least-squares fitting:')
    equation(a,assets,'spline')
    a.p('Concatenating the coordinate coefficients produced an 18-value vector c per trial. Across training trials, these vectors formed an N<sub>train</sub> x 18 matrix. PCA was fitted to this matrix to learn a shared n-dimensional coefficient subspace. Raw and coefficient-standardized variants were compared using validation trajectory MSE, and the lower-error variant was retained. The PCA basis and scaling statistics were never fitted to test participants.')
    a.p('Writing m for the training coefficient mean, d for the coefficient scaling vector and V for the 18 x n principal-component matrix, encoding and reconstruction can be expressed as:')
    equation(a,assets,'pca')
    a.p('Division and multiplication by d act coordinate-wise; d equals one for the unstandardized variant. PCA selects directions of variance in coefficient space. Its fitting objective is therefore distinct from minimizing trajectory MSE directly, although trajectory MSE is used to select the scaling variant.')
    a.p('The reconstructed coefficient vector was separated into x and y blocks. Multiplying each reconstructed coefficient block by B recovered its coordinate sequence. Test trajectories were fitted to the fixed spline basis to obtain coefficients and then projected through the training-fitted PCA basis. Thus, the final trial code contained n values, not all 18 spline coefficients.')
    a.h('3.2 Ridge regression for spline timing', True)
    a.p('Shape-only PCA did not contain explicit duration targets. We therefore fitted a separate Ridge regression to predict the two standardized log-durations from the concatenation of the n PCA scores and five task-condition values. Its input matrix had N<sub>train</sub> rows and n+5 columns, standardized using training statistics. For input matrix U and target matrix Y, the fitted weights W and intercept b minimized:')
    equation(a,assets,'ridge')
    a.p('The penalty reduced the size of regression coefficients; the intercept was unpenalized. Alpha was selected from 0.01, 0.1, 1, 10 and 100 by validation MSE in standardized log-time space. The selected regression was fitted on training participants and inverted to seconds at prediction time. This regression predicts timing; inverse PCA and the spline basis reconstruct the spatial trajectory.')
    a.page()
    a.h('3.3 Neural encoder-decoder models', True)
    a.p('The conditional variational autoencoder (CVAE) learned a nonlinear trajectory representation within the variational encoder-decoder framework [1,2]. The 200-coordinate input was standardized using a separate training mean and standard deviation for each coordinate. Five condition values were concatenated to it: three one-hot starting-category indicators, a binary starting-side value and continuous executed target speed. Speed was calculated from the target trajectory and divided by 1920 pixels to express it in screen widths/s. '+ask('Confirm the 1920-pixel screen-width assumption.'))
    a.p('Two fully connected layers of 256 ReLU units produced an n-dimensional posterior mean and log-variance vector. Training drew a latent sample through Gaussian reparameterization. The decoder concatenated z with the five conditions and applied two further 256-unit ReLU layers. Separate linear heads predicted 200 standardized coordinates and two standardized log-durations.')
    equation(a,assets,'sample')
    a.p('The per-trial objective combined coordinate reconstruction, duration prediction and regularization of the approximate posterior toward a standard-normal prior:')
    equation(a,assets,'loss')
    a.p('Here v denotes standardized trajectory coordinates, y the two standardized log-duration targets, and c the condition vector. Coordinate and timing errors are sums over their respective outputs; the complete loss is averaged over the batch. For the diagonal Gaussian posterior, the KL term sums contributions from all n coordinates. Beta increased from zero to one in 50 increments, reaching one at epoch 51.')
    equation(a,assets,'kl')
    a.p('Training used Adam with initial learning rate 0.001, batches of 64 and gradient clipping at norm 5. Validation controlled learning-rate reduction and checkpoint selection using the full-target-KL objective. Training stopped after 25 epochs without improvement or at 150 epochs. Seeds 42, 43 and 44 repeated training. For deterministic reconstruction, the decoder received the posterior mean rather than a sampled code; its outputs were then returned to the original coordinate and timing scales.')
    a.p('Two ablations isolated changes to this architecture. Conditional AE (CAE) retained the condition inputs but replaced stochastic sampling with a deterministic code and removed the KL term. Unconditional VAE retained sampling and KL but replaced all condition inputs with zeros at both encoder and decoder. Its mathematical formulation consequently omitted the dependence on c. The same trajectory and timing targets were used in these comparisons.')
    a.h('3.4 Condition-only control and dashboard scope', True)
    a.p('A separate condition-only Ridge model predicted the 200 trajectory coordinates from the five task values. It received neither the observed trajectory nor a participant fingerprint, providing a reference for prediction from task information alone. This differs from the spline timing regression, whose inputs include a trajectory code.')
    a.p('The dashboard supports CVAE and spline + PCA at n=2, 3, 4 and 8, and VAE and CAE at n=3 and 8. VAE at n=8 is the default for distribution exploration because it has the lowest cohort-average KS, energy and MMD-squared distances in the tested matrix (Section 5). This endpoint-specific numerical ranking does not imply superiority on every task. Conditions are inactive for VAE and affect only timing for spline + PCA. No n=16 result is included in the matched study.')
    a.page()
    a.h('4 Trajectory reconstruction results')
    a.p('The first evaluation asked how much of an observed trajectory each compact representation could recover. Both the spline and neural models received the complete held-out trajectory, compressed it to n values and decoded it to the original 100 x 2 shape. Reconstruction MSE was calculated as:')
    equation(a,assets,'mse')
    a.p('Trial errors were averaged within participants, then across neural seeds and finally across the 28 participants with equal weight. This preserves each participant as the reporting unit despite unequal trial counts. Spline fits were deterministic within each fold and dimension. Errors are in squared tracker units.')
    labels={'spline_pca':'Spline + PCA','unconditional_vae':'VAE','conditional_ae':'Conditional AE','cvae':'CVAE','condition_ridge':'Condition-only Ridge'}
    rows=[['Model','n=3 MSE','n=8 MSE']]
    for family,label in labels.items():
        rows.append([label,*[f'{means.loc[(family,0 if family=="condition_ridge" else n)]:.6f}' for n in [3,8]]])
    a.table(rows,'<b>Table 2.</b> Participant-balanced reconstruction error. Lower is better. Condition-only Ridge has no latent dimension; its result is repeated for reference.',[88*mm,39*mm,39*mm])
    a.figure(assets/'participant_mse.png','<b>Figure 5.</b> Participant errors after neural-seed averaging. Each point represents one participant; black bars show cohort means. The vertical axis is logarithmic.',59*mm)
    a.p('Spline + PCA achieved the lowest mean reconstruction error at both capacities. Among neural models, VAE was best at n=3 (0.148299), whereas CAE was best at n=8 (0.025968). CVAE error decreased from 0.176981 to 0.032481, and spline error decreased from 0.097255 to 0.022772, when capacity increased from three to eight values.')
    a.p('Exploratory two-sided paired Wilcoxon tests used 28 seed-averaged participant values, Pratt zero handling and differences rounded to 12 decimals [3]. Benjamini-Hochberg adjustment covered 140 comparisons: ten model pairs, two dimensions and seven endpoints. At n=3, VAE had lower MSE than CVAE (q=0.00163) and CAE (q=0.03695). At n=8, CAE had lower MSE than both variational models (q&lt;0.000001). All six spline-neural contrasts favored spline after this adjustment.')
    a.p('Holm adjustment across the same 140 tests retained the two n=8 neural contrasts but not the two n=3 contrasts. Because folds share development participants, these tests provide exploratory within-cohort evidence rather than independent population confirmation [4].')
    a.page()
    a.h('4.1 Recorded and reconstructed trajectories', True)
    a.figure(assets/'reconstructions.png','<b>Figure 6.</b> Recorded inputs and decoded outputs, using neural seed 42. Blue represents VAE at n=3 and CAE at n=8. All panels share axis limits; the lateral axis is expanded relative to the forward axis to reveal differences. These are reconstructions, not newly generated movements.',103*mm)
    a.p('Examples were chosen by a fixed error-ranking rule. Participants were ranked by mean n=3 reconstruction MSE across the four compression families, averaging neural seeds first. The 14th and 26th participants represented the central and higher-error portions of the ranking. Within each participant, the median-ranked trial under the same family-averaged error was selected. The same input was displayed at both capacities.')
    a.p('The selected trials were '+ '; '.join(f"<b>{ex['trial_id']}</b> (fold {ex['fold']})" for ex in chosen)+'. Selection used held-out errors for illustration only. The aggregate comparison includes all 28 participants; a model with the lowest cohort mean need not be best on each displayed trial.')
    a.p('Reconstruction establishes how accurately the models compress observed paths. The fingerprint objective requires a further test: whether a code estimated from one set of a participant\'s movements can reproduce the distribution of other movements. The subsequent sections therefore evaluate duration prediction, generated feature distributions and participant-specific information. Side-by-side generation figures will be labeled separately from these input-output reconstructions.')
    from production.generation_section import write_generation
    write_generation(a,assets)
    from production.remaining_results import write_remaining
    write_remaining(a,assets,a.remaining_evidence)
    a.page()
    a.h('References')
    for ref in ['[1] Kingma DP, Welling M. Auto-Encoding Variational Bayes. ICLR, 2014. arXiv:1312.6114.','[2] Sohn K, Lee H, Yan X. Learning Structured Output Representation using Deep Conditional Generative Models. NeurIPS 28, 2015.','[3] SciPy developers. scipy.stats.wilcoxon and scipy.stats.ks_2samp documentation. Evaluations executed with SciPy 1.16.3.','[4] Bengio Y, Grandvalet Y. No unbiased estimator of the variance of K-fold cross-validation. JMLR. 2004;5:1089-1105.']:
        a.p(ref,'caption')
    a.p('[5] Gretton A, Borgwardt KM, Rasch MJ, Scholkopf B, Smola A. A Kernel Two-Sample Test. JMLR. 2012;13:723-773. https://www.jmlr.org/papers/v13/gretton12a.html','caption')
    a.p('[6] Flash T, Hogan N. The coordination of arm movements: an experimentally confirmed mathematical model. J Neurosci. 1985;5:1688-1703. doi:10.1523/JNEUROSCI.05-07-01688.1985.','caption')
    a.p('[7] Friedman J. submovements. https://github.com/JasonFriedman/submovements. Local reference revision 9c2f40ccc922d542242329c46cfd524c21188b4a; adapted implementation, GPL-3.0.','caption')
    a.p('[8] Rohrer B, Hogan N. Avoiding spurious submovement decompositions II: a scattershot algorithm. Biological Cybernetics. 2006;94:409-414. doi:10.1007/s00422-006-0055-y.','caption')
